  'help.faq.notReceiving.q': 'Não estou recebendo emails',
  'help.faq.notReceiving.a': 'Verifique a pasta de Spam primeiro. Certifique-se que seu armazenamento não está cheio. Se o problema continuar, confirme que o remetente tem o endereço correto e crie um ticket.',
  'help.faq.cantSend.q': 'Não consigo enviar emails',
