  'help.faq.accountSecurity.q': 'Acho que minha conta foi comprometida',
  'help.faq.accountSecurity.a': 'Altere sua senha imediatamente. Verifique a pasta Enviados por mensagens que você não enviou. Ative a autenticação em duas etapas em Configurações > Segurança. Se necessário, crie um ticket urgente.',
  'help.faq.appAccess.q': 'Como acesso o app no celular?',
  'help.faq.appAccess.a': 'Você pode acessar o Chatyy pelo navegador em chatyy.com.br, ou baixar nosso app na loja de aplicativos do seu dispositivo.',

  // Privacy modal
  'privacy.title': 'Política de Privacidade',
  'privacy.subtitle': 'Como protegemos e tratamos seus dados',
  'privacy.lastUpdated': 'Última atualização: Março 2026',
  'privacy.dataCollection.title': 'Coleta de Dados',
  'privacy.dataCollection.body': 'Coletamos apenas as informações necessárias para o serviço de email: seu nome, endereço de email e o conteúdo das mensagens enviadas e recebidas. Não vendemos nem compartilhamos seus dados pessoais com terceiros para fins de marketing.',
  'privacy.dataUsage.title': 'Como Usamos Seus Dados',
  'privacy.dataUsage.body': 'Seus dados são usados exclusivamente para operar e melhorar o serviço de email, incluindo entrega de mensagens, filtragem de spam, recursos de IA (com seu consentimento) e segurança da conta.',
  'privacy.dataSecurity.title': 'Segurança dos Dados',
  'privacy.dataSecurity.body': 'Usamos criptografia padrão da indústria (TLS/SSL) para todos os dados em trânsito e em repouso. Sessões são protegidas com tokens criptografados e proteção CSRF. Auditamos regularmente nossas práticas de segurança.',
  'privacy.cookies.title': 'Cookies e Armazenamento Local',
  'privacy.cookies.body': 'Usamos cookies essenciais e armazenamento local para manter sua sessão, lembrar suas preferencias (tema, idioma) e proporcionar uma experiencia fluida. Não usamos cookies de rastreamento de terceiros.',
  'privacy.thirdParties.title': 'Serviços de Terceiros',
  'privacy.thirdParties.body': 'Podemos usar serviços de terceiros para funcionalidades especificas como IA (Anthropic Claude) e notificações push. Esses serviços seguem suas próprias políticas de privacidade e processam apenas o mínimo de dados necessário.',
  'privacy.rights.title': 'Seus Direitos',
  'privacy.rights.body': 'Você tem o direito de acessar, corrigir, exportar ou excluir seus dados pessoais a qualquer momento. Você pode gerenciar seus dados em Configurações ou contatando nosso suporte.',
  'privacy.contact.title': 'Fale Conosco',
  'privacy.contact.body': 'Para questões de privacidade ou solicitações de dados, entre em contato pelo privacy@chatyy.com.br. Responderemos em até 30 dias.',

  // Terms modal
  'terms.title': 'Termos de Serviço',
  'terms.subtitle': 'Diretrizes de uso do Chatyy',
  'terms.lastUpdated': 'Última atualização: Março 2026',
  'terms.acceptance.title': 'Aceitacao dos Termos',
  'terms.acceptance.body': 'Ao acessar ou usar o Chatyy, você concorda com estes Termos de Serviço. Se não concordar com qualquer parte destes termos, não utilize o serviço.',
  'terms.services.title': 'Descrição dos Serviços',
  'terms.services.body': 'O Chatyy fornece serviços de comunicação por email incluindo envio, recebimento e gerenciamento de emails, além de recursos de IA, integração com calendário e videoconferência.',
  'terms.accounts.title': 'Contas de Usuário',
  'terms.accounts.body': 'Você e responsável por manter a segurança das suas credenciais. Não compartilhe sua senha nem permita acesso não autorizado a sua conta. Você deve ter pelo menos 13 anos para usar este serviço.',
  'terms.conduct.title': 'Uso Aceitável',
  'terms.conduct.body': 'Você concorda em não usar o serviço para enviar spam, malware, phishing ou qualquer conteúdo ilegal. Não tente acessar contas de outros usuários ou interromper a infraestrutura do serviço.',
  'terms.content.title': 'Propriedade do Conteúdo',
  'terms.content.body': 'Você mantém a propriedade de todo conteúdo que cria e envia pelo serviço. Não reivindicamos propriedade sobre seus emails ou anexos. Podemos processar o conteúdo conforme necessário para fornecer o serviço.',
  'terms.limitation.title': 'Limitação de Responsabilidade',
  'terms.limitation.body': 'O Chatyy é fornecido "como está". Buscamos 99,9% de disponibilidade mas não garantimos serviço ininterrupto. Não somos responsáveis por danos indiretos, incidentais ou consequentes decorrentes do uso do serviço.',
  'terms.termination.title': 'Encerramento de Conta',
  'terms.termination.body': 'Podemos suspender ou encerrar contas que violem estes termos. Você pode excluir sua conta a qualquer momento em Configurações. Após o encerramento, seus dados serão excluídos em até 30 dias.',
  'terms.changes.title': 'Alterações nós Termos',
  'terms.changes.body': 'Podemos atualizar estes termos periodicamente. Notificaremos sobre alterações significativas por email ou notificação no app. O uso continuado após as alterações constitui aceitação dos termos atualizados.',

